    [Fact]public async Task NonLearner_CannotEnroll(){await using var p=Provider();using var s=p.CreateScope();await Roles(s);var u=await User(s,"admin@test",AppRoles.Admin);var c=await Course(s,true);Assert.False((await E(s).EnrollFreeAsync(c.Training.Id,u.Id)).Succeeded);}
    [Fact]public async Task ArchivedTraining_RejectsEnrollment(){await using var p=Provider();using var s=p.CreateScope();await Roles(s);var u=await User(s,"l@test",AppRoles.Learner);var c=await Course(s,true,true);Assert.False((await E(s).CreateByAdminAsync(new(u.Id,c.Training.Id,true,"admin"))).Succeeded);}
    [Fact]public async Task FreeTraining_AllowsDirectEnrollment(){await using var p=Provider();using var s=p.CreateScope();await Roles(s);var u=await User(s,"l@test",AppRoles.Learner);var c=await Course(s,true);Assert.True((await E(s).EnrollFreeAsync(c.Training.Id,u.Id)).Succeeded);}
    [Fact]public async Task PaidTraining_RejectsDirectEnrollment(){await using var p=Provider();using var s=p.CreateScope();await Roles(s);var u=await User(s,"l@test",AppRoles.Learner);var c=await Course(s,false);Assert.False((await E(s).EnrollFreeAsync(c.Training.Id,u.Id)).Succeeded);}
    [Fact]public async Task ActiveDuplicate_IsRejected(){await using var p=Provider();using var s=p.CreateScope();await Roles(s);var u=await User(s,"l@test",AppRoles.Learner);var c=await Course(s,true);await E(s).EnrollFreeAsync(c.Training.Id,u.Id);Assert.False((await E(s).EnrollFreeAsync(c.Training.Id,u.Id)).Succeeded);}
    [Fact]public async Task ActiveEnrollment_AllowsAccess(){await using var p=Provider();using var s=p.CreateScope();var c=await Course(s);var e=await Enrollment(s,c,"x",EnrollmentStatus.Active);Assert.True(await E(s).CanAccessTrainingAsync(c.Training.Id,e.LearnerId));}
    [Fact]public async Task PendingEnrollment_DeniesAccess(){await using var p=Provider();using var s=p.CreateScope();var c=await Course(s);var e=await Enrollment(s,c,"x",EnrollmentStatus.Pending);Assert.False(await E(s).CanAccessTrainingAsync(c.Training.Id,e.LearnerId));}
    [Fact]public async Task SuspendedEnrollment_DeniesAccess(){await using var p=Provider();using var s=p.CreateScope();var c=await Course(s);var e=await Enrollment(s,c,"x",EnrollmentStatus.Suspended);Assert.False(await E(s).CanAccessTrainingAsync(c.Training.Id,e.LearnerId));}
    [Fact]public async Task CompletedEnrollment_KeepsAccess(){await using var p=Provider();using var s=p.CreateScope();var c=await Course(s);var e=await Enrollment(s,c,"x",EnrollmentStatus.Completed);Assert.True(await E(s).CanAccessTrainingAsync(c.Training.Id,e.LearnerId));}
    [Fact]public async Task Admin_CanActivateEnrollment(){await using var p=Provider();using var s=p.CreateScope();var c=await Course(s);var e=await Enrollment(s,c,"x",EnrollmentStatus.Pending);Assert.True((await E(s).ActivateAsync(e.Id)).Succeeded);Assert.Equal(EnrollmentStatus.Active,(await Db(s).Enrollments.FindAsync(e.Id))!.Status);}

    [Fact]public async Task FirstAccess_CreatesProgress(){await using var p=Provider();using var s=p.CreateScope();var setup=await Ready(s);var r=await P(s).RecordAccessAsync(setup.Course.Lesson.Id,setup.UserId);Assert.True(r.Succeeded);Assert.Single(Db(s).LessonProgresses);}
    [Fact]public async Task FirstAccessAt_IsNotOverwritten(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var first=await P(s).RecordAccessAsync(x.Course.Lesson.Id,x.UserId);var time=first.Value!.FirstAccessedAt;await Task.Delay(5);var second=await P(s).RecordAccessAsync(x.Course.Lesson.Id,x.UserId);Assert.Equal(time,second.Value!.FirstAccessedAt);}
    [Fact]public async Task LastAccessAt_IsUpdated(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var first=await P(s).RecordAccessAsync(x.Course.Lesson.Id,x.UserId);await Task.Delay(5);var second=await P(s).RecordAccessAsync(x.Course.Lesson.Id,x.UserId);Assert.True(second.Value!.LastAccessedAt>first.Value!.LastAccessedAt);}
    [Fact]public async Task Lesson_CanBeCompleted(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var r=await P(s).CompleteAsync(x.Course.Lesson.Id,x.UserId);Assert.True(r.Succeeded);Assert.Equal(LessonProgressStatus.Completed,(await Db(s).LessonProgresses.SingleAsync()).Status);}
    [Fact]public async Task OnlyOneProgress_PerEnrollmentLesson(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);await P(s).RecordAccessAsync(x.Course.Lesson.Id,x.UserId);await P(s).RecordAccessAsync(x.Course.Lesson.Id,x.UserId);Assert.Single(Db(s).LessonProgresses);}
    [Fact]public async Task LessonFromOtherTraining_IsRejected(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var other=await Course(s);Assert.False((await P(s).RecordAccessAsync(other.Lesson.Id,x.UserId)).Succeeded);}
    [Fact]public async Task ArchivedLessons_AreExcludedFromProgress(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);x.Course.SecondLesson.IsArchived=true;await Db(s).SaveChangesAsync();var r=await P(s).CompleteAsync(x.Course.Lesson.Id,x.UserId);Assert.Equal(100,r.Value!.ProgressPercentage);}
    [Fact]public async Task Progress_IsCalculatedCorrectly(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var r=await P(s).CompleteAsync(x.Course.Lesson.Id,x.UserId);Assert.Equal(50,r.Value!.ProgressPercentage);}
    [Fact]public async Task Enrollment_CompletesAtHundredPercent(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);await P(s).CompleteAsync(x.Course.Lesson.Id,x.UserId);var r=await P(s).CompleteAsync(x.Course.SecondLesson.Id,x.UserId);Assert.Equal(EnrollmentStatus.Completed,r.Value!.EnrollmentStatus);}

    [Fact]public async Task Attempt_RequiresEnrollment(){await using var p=Provider();using var s=p.CreateScope();var c=await Course(s);Assert.False((await A(s).StartAsync(new(c.Assessment.Id,"none"))).Succeeded);}
    [Fact]public async Task AssessmentFromOtherTraining_IsRejected(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var other=await Course(s);Assert.False((await A(s).StartAsync(new(other.Assessment.Id,x.UserId))).Succeeded);}
    [Fact]public async Task AttemptNumber_StartsAtOne(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var r=await A(s).StartAsync(new(x.Course.Assessment.Id,x.UserId));Assert.Equal(1,(await Db(s).AssessmentAttempts.FindAsync(r.Value))!.AttemptNumber);}
    [Fact]public async Task AttemptNumber_Increments(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var first=await Start(s,x);await A(s).SubmitAsync(new(first,x.UserId,[]));var second=await A(s).StartAsync(new(x.Course.Assessment.Id,x.UserId));Assert.Equal(2,(await Db(s).AssessmentAttempts.FindAsync(second.Value))!.AttemptNumber);}
    [Fact]public async Task OnlyOneInProgressAttempt_IsReturned(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var a=await A(s).StartAsync(new(x.Course.Assessment.Id,x.UserId));var b=await A(s).StartAsync(new(x.Course.Assessment.Id,x.UserId));Assert.Equal(a.Value,b.Value);}
    [Fact]public async Task MaximumAttempts_IsRespected(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s,maxAttempts:1);var id=await Start(s,x);await A(s).SubmitAsync(new(id,x.UserId,[]));Assert.False((await A(s).StartAsync(new(x.Course.Assessment.Id,x.UserId))).Succeeded);}
    [Fact]public async Task ExpiresAt_IsCalculated(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s,time:10);var id=await Start(s,x);var a=await Db(s).AssessmentAttempts.FindAsync(id);Assert.InRange((a!.ExpiresAt-a.StartedAt)!.Value.TotalMinutes,9.9,10.1);}
    [Fact]public async Task ExpiredAttempt_CannotBeModified(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);var a=await Db(s).AssessmentAttempts.FindAsync(id);a!.ExpiresAt=DateTime.UtcNow.AddSeconds(-1);await Db(s).SaveChangesAsync();Assert.False((await A(s).SaveAnswersAsync(id,x.UserId,[])).Succeeded);}
    [Fact]public async Task SubmittedAttempt_CannotBeModified(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);await A(s).SubmitAsync(new(id,x.UserId,[]));Assert.False((await A(s).SaveAnswersAsync(id,x.UserId,[])).Succeeded);}
    [Fact]public async Task MaximumScore_IsCalculated(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);Assert.Equal(5,(await Db(s).AssessmentAttempts.FindAsync(id))!.MaximumScore);}
    [Fact]public async Task AttemptSnapshots_AreCreated(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);var snapshots=await Db(s).AttemptQuestions.Where(q=>q.AssessmentAttemptId==id).ToListAsync();Assert.Equal(4,snapshots.Count);Assert.All(snapshots,q=>Assert.NotEmpty(q.StatementSnapshot));}
    [Fact]public async Task ShuffledOrder_RemainsStable(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s,shuffle:true);var id=await Start(s,x);var one=(await A(s).GetAttemptAsync(id,x.UserId))!.Questions.Select(q=>q.AttemptQuestionId);var two=(await A(s).GetAttemptAsync(id,x.UserId))!.Questions.Select(q=>q.AttemptQuestionId);Assert.Equal(one,two);}
    [Fact]public async Task DoubleSubmission_IsRejected(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);Assert.True((await A(s).SubmitAsync(new(id,x.UserId,[]))).Succeeded);Assert.False((await A(s).SubmitAsync(new(id,x.UserId,[]))).Succeeded);}

    [Fact]public void SingleChoiceCorrect_GivesAllPoints(){Assert.Equal(2,Score(QuestionType.SingleChoice,"1",null,[1],2).Score);}
    [Fact]public void SingleChoiceIncorrect_GivesZero(){Assert.Equal(0,Score(QuestionType.SingleChoice,"1",null,[2],2).Score);}
    [Fact]public void MultipleChoiceExact_GivesAllPoints(){Assert.Equal(3,Score(QuestionType.MultipleChoice,"1,2",null,[1,2],3).Score);}
    [Fact]public void MultipleChoiceIncomplete_GivesZero(){Assert.Equal(0,Score(QuestionType.MultipleChoice,"1,2",null,[1],3).Score);}
    [Fact]public void MultipleChoiceWithWrongChoice_GivesZero(){Assert.Equal(0,Score(QuestionType.MultipleChoice,"1,2",null,[1,2,3],3).Score);}
    [Fact]public void TrueFalse_IsScored(){Assert.True(Score(QuestionType.TrueFalse,"10",null,[10],1).Passed);}
    [Fact]public void ShortAnswer_IgnoresCase(){Assert.Equal(1,Score(QuestionType.ShortAnswer,null,"Program.cs",[],1,"program.CS").Score);}
    [Fact]public void ShortAnswer_TrimsSpaces(){Assert.Equal(1,Score(QuestionType.ShortAnswer,null,"Program.cs",[],1,"  Program.cs  ").Score);}
    [Fact]public void TotalScore_IsCalculated(){var svc=new AttemptScoringService();var r=svc.Score([new(1,QuestionType.SingleChoice,2,"1",null,[1],null),new(2,QuestionType.ShortAnswer,3,null,"x",[],"x")],50);Assert.Equal(5,r.Score);}
    [Fact]public void Percentage_IsCalculated(){var r=Score(QuestionType.SingleChoice,"1",null,[1],2);Assert.Equal(100,r.PercentageScore);}
    [Fact]public void Passed_UsesPassingScore(){var svc=new AttemptScoringService();var r=svc.Score([new(1,QuestionType.SingleChoice,1,"1",null,[2],null)],70);Assert.False(r.Passed);}

    [Fact]public async Task Learner_CannotSeeOtherAttempt(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);Assert.Null(await A(s).GetAttemptAsync(id,"other"));}
