    [Fact]public async Task CorrectAnswers_AreVisibleWhenEnabled(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s,showCorrect:true);var id=await Start(s,x);await SubmitCorrectSingle(s,x,id);var r=await A(s).GetResultAsync(id,x.UserId);Assert.Contains(r!.Questions,q=>q.CorrectAnswer is not null);}
    [Fact]public async Task CorrectAnswers_AreHiddenWhenDisabled(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s,showCorrect:false);var id=await Start(s,x);await SubmitCorrectSingle(s,x,id);var r=await A(s).GetResultAsync(id,x.UserId);Assert.All(r!.Questions,q=>Assert.Null(q.CorrectAnswer));}
    [Fact]public async Task ExpectedAnswer_IsHiddenWhenConfigured(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s,showCorrect:false);var id=await Start(s,x);await A(s).SubmitAsync(new(id,x.UserId,[]));var r=await A(s).GetResultAsync(id,x.UserId);Assert.DoesNotContain(r!.Questions,q=>q.CorrectAnswer=="Program.cs");}
    [Fact]public async Task ExpiredAttempt_HasExpiredStatus(){await using var p=Provider();using var s=p.CreateScope();var x=await Ready(s);var id=await Start(s,x);var a=await Db(s).AssessmentAttempts.FindAsync(id);a!.ExpiresAt=DateTime.UtcNow.AddSeconds(-1);await Db(s).SaveChangesAsync();await A(s).GetAttemptAsync(id,x.UserId);Assert.Equal(AttemptStatus.Expired,(await Db(s).AssessmentAttempts.FindAsync(id))!.Status);}

    [Fact]public async Task Seed_IsIdempotent(){await using var p=Provider(true);using var s=p.CreateScope();await Roles(s);var seed=s.ServiceProvider.GetRequiredService<DevelopmentDataSeeder>();await seed.SeedAsync();var first=(await Db(s).Enrollments.CountAsync(),await Db(s).LessonProgresses.CountAsync());Db(s).ChangeTracker.Clear();await seed.SeedAsync();Assert.Equal(first,(await Db(s).Enrollments.CountAsync(),await Db(s).LessonProgresses.CountAsync()));}
    [Fact]public async Task Seed_CreatesLearner(){await using var p=Provider(true);using var s=p.CreateScope();await Roles(s);await s.ServiceProvider.GetRequiredService<DevelopmentDataSeeder>().SeedAsync();Assert.NotNull(await Users(s).FindByEmailAsync("learner@training.local"));}
    [Fact]public async Task Seed_CreatesCoherentEnrollment(){await using var p=Provider(true);using var s=p.CreateScope();await Roles(s);await s.ServiceProvider.GetRequiredService<DevelopmentDataSeeder>().SeedAsync();var e=await Db(s).Enrollments.Include(x=>x.LessonProgresses).SingleAsync();Assert.Equal(EnrollmentStatus.Active,e.Status);Assert.InRange(e.ProgressPercentage,0.01m,99.99m);Assert.Contains(e.LessonProgresses,x=>x.Status==LessonProgressStatus.Completed);}

    private sealed record CourseData(Training Training,TrainingModule Module,Lesson Lesson,Lesson SecondLesson,Assessment Assessment,Question Single);
    private sealed record ReadyData(CourseData Course,string UserId,Enrollment Enrollment);
    private static ServiceProvider Provider(bool seed=false){var c=new ServiceCollection();c.AddLogging();c.AddDbContext<ApplicationDbContext>(o=>o.UseInMemoryDatabase(Guid.NewGuid().ToString()));c.AddIdentityCore<ApplicationUser>().AddRoles<IdentityRole>().AddEntityFrameworkStores<ApplicationDbContext>();c.AddScoped<IEnrollmentService,EnrollmentService>();c.AddScoped<ILessonProgressService,LessonProgressService>();c.AddSingleton<IAttemptScoringService,AttemptScoringService>();c.AddScoped<IAssessmentAttemptService,AssessmentAttemptService>();if(seed){c.AddSingleton<IOptions<SeedTrainerOptions>>(Options.Create(new SeedTrainerOptions{Email="trainer@training.local",Password="Trainer123!",FirstName="T",LastName="D"}));c.AddSingleton<IOptions<SeedLearnerOptions>>(Options.Create(new SeedLearnerOptions()));c.AddScoped<DevelopmentDataSeeder>();}return c.BuildServiceProvider();}
    private static ApplicationDbContext Db(IServiceScope s)=>s.ServiceProvider.GetRequiredService<ApplicationDbContext>();private static UserManager<ApplicationUser>Users(IServiceScope s)=>s.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();private static IEnrollmentService E(IServiceScope s)=>s.ServiceProvider.GetRequiredService<IEnrollmentService>();private static ILessonProgressService P(IServiceScope s)=>s.ServiceProvider.GetRequiredService<ILessonProgressService>();private static IAssessmentAttemptService A(IServiceScope s)=>s.ServiceProvider.GetRequiredService<IAssessmentAttemptService>();
    private static async Task Roles(IServiceScope s){var r=s.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();foreach(var role in AppRoles.All)if(!await r.RoleExistsAsync(role))await r.CreateAsync(new IdentityRole(role));}
    private static async Task<ApplicationUser>User(IServiceScope s,string email,string role){var u=new ApplicationUser{UserName=email,Email=email,FirstName="Test",LastName="User"};await Users(s).CreateAsync(u,"Password1!");await Users(s).AddToRoleAsync(u,role);return u;}
    private static async Task<CourseData>Course(IServiceScope s,bool free=true,bool archived=false,string? trainerId=null,bool showCorrect=true,int? maxAttempts=3,int? time=10,bool shuffle=false){var cat=new Category{Name="C"+Guid.NewGuid(),Slug="c-"+Guid.NewGuid()};var tr=new Training{Title="Course",Slug="course-"+Guid.NewGuid(),ShortDescription="Short",Description="D",Category=cat,Language="Français",EstimatedDurationHours=1,IsFree=free,Price=free?0:100,Status=archived?TrainingStatus.Archived:TrainingStatus.Published,TrainerId=trainerId};var m=new TrainingModule{Training=tr,Title="Module",Slug="module",Order=1,IsPublished=true};var l=new Lesson{TrainingModule=m,Title="Private",Slug="private",Order=1,IsPublished=true,IsPreview=false};var l2=new Lesson{TrainingModule=m,Title="Second",Slug="second",Order=2,IsPublished=true};var ass=new Assessment{Lesson=l,Title="Quiz",Slug="quiz",Order=1,PassingScore=70,MaximumAttempts=maxAttempts,TimeLimitMinutes=time,ShuffleQuestions=shuffle,ShowCorrectAnswers=showCorrect,IsPublished=true};var single=new Question{Assessment=ass,QuestionType=QuestionType.SingleChoice,Statement="Single",Order=1,Points=1,IsPublished=true};single.AnswerOptions.Add(new(){Text="A",Order=1,IsCorrect=true});single.AnswerOptions.Add(new(){Text="B",Order=2});var multi=new Question{Assessment=ass,QuestionType=QuestionType.MultipleChoice,Statement="Multi",Order=2,Points=2,IsPublished=true};multi.AnswerOptions.Add(new(){Text="A",Order=1,IsCorrect=true});multi.AnswerOptions.Add(new(){Text="B",Order=2,IsCorrect=true});multi.AnswerOptions.Add(new(){Text="C",Order=3});var tf=new Question{Assessment=ass,QuestionType=QuestionType.TrueFalse,Statement="TF",Order=3,Points=1,IsPublished=true};tf.AnswerOptions.Add(new(){Text="Vrai",Order=1,IsCorrect=true});tf.AnswerOptions.Add(new(){Text="Faux",Order=2});var shortQ=new Question{Assessment=ass,QuestionType=QuestionType.ShortAnswer,Statement="Short",ExpectedAnswer="Program.cs",Order=4,Points=1,IsPublished=true};Db(s).AddRange(l2,single,multi,tf,shortQ);await Db(s).SaveChangesAsync();return new(tr,m,l,l2,ass,single);}
    private static async Task<Enrollment>Enrollment(IServiceScope s,CourseData c,string learner,EnrollmentStatus status){var e=new Enrollment{TrainingId=c.Training.Id,LearnerId=learner,Status=status,EnrolledAt=DateTime.UtcNow};Db(s).Add(e);await Db(s).SaveChangesAsync();return e;}
    private static async Task<ReadyData>Ready(IServiceScope s,bool showCorrect=true,int? maxAttempts=3,int? time=10,bool shuffle=false,string? trainerId=null){var c=await Course(s,true,false,trainerId,showCorrect,maxAttempts,time,shuffle);var id="learner-"+Guid.NewGuid();var e=await Enrollment(s,c,id,EnrollmentStatus.Active);return new(c,id,e);}
    private static async Task<int>Start(IServiceScope s,ReadyData x)=>(await A(s).StartAsync(new(x.Course.Assessment.Id,x.UserId))).Value;
    private static ScoringResult Score(QuestionType type,string? correct,string? expected,IReadOnlyCollection<int> selected,decimal points,string? text=null)=>new AttemptScoringService().Score([new(1,type,points,correct,expected,selected,text)],50);
    private static string?Role<T>()=>typeof(T).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single().Roles;
    private static async Task SubmitCorrectSingle(IServiceScope s,ReadyData x,int id){var detail=await A(s).GetAttemptAsync(id,x.UserId);var q=detail!.Questions.Single(q=>q.QuestionType==QuestionType.SingleChoice);var option=q.Options.Single(o=>o.Text=="A");await A(s).SubmitAsync(new(id,x.UserId,[new(q.AttemptQuestionId,[option.Id],null)]));}
}
